asks = [(10000, 30), (10050, 50), (10100, 100)]
def match(asks, limit, qty, tif):
    can = sum(q for p, q in asks if p <= limit)
    if tif == "FOK" and can < qty:
        return "전량 취소(체결 가능 %d주 < %d주)" % (can, qty)
    fills, left = [], qty
    for p, q in asks:
        if p > limit or left == 0:
            break
        f = min(q, left); fills.append((p, f)); left -= f
    rest = {"IOC": "잔량 %d주 취소" % left, "DAY": "잔량 %d주 호가창에 대기" % left}[tif]
    return "체결 %s, %s" % (fills, rest)
for tif in ["DAY", "IOC", "FOK"]:
    print(tif, match(asks, 10050, 100, tif))

# 출력
# DAY 체결 [(10000, 30), (10050, 50)], 잔량 20주 호가창에 대기
# IOC 체결 [(10000, 30), (10050, 50)], 잔량 20주 취소
# FOK 전량 취소(체결 가능 80주 < 100주)

from decimal import Decimal as D
MULT = 250_000  # 코스피200 옵션 거래승수(원)
def tick(premium):
    return D("0.01") if premium < 10 else D("0.05")
for prem, n in [(D("2.35"), 3), (D("12.40"), 1)]:
    print(f"프리미엄 {prem}pt x {n}계약 = {int(prem*MULT*n):,}원 · 호가 단위 {tick(prem)}pt = {int(tick(prem)*MULT):,}원")

# 출력
# 프리미엄 2.35pt x 3계약 = 1,762,500원 · 호가 단위 0.01pt = 2,500원
# 프리미엄 12.40pt x 1계약 = 3,100,000원 · 호가 단위 0.05pt = 12,500원
